/**
 * Retrieves the full chart of accounts
 */
export const getAccounts = (config: OpenAPIClientConfig, request: {
  query?: {
    /** Filter by an any element */
    where?: string;
    /** Order by an any element */
    order?: string;
  };
  headers: {
    /** Xero identifier for Tenant */
    "xero-tenant-id": string;
    /** Only records created or modified since this timestamp will be returned */
    "If-Modified-Since"?: string;
  };
}): Promise<
  OpenAPIResponses<{
    /** Success - return response of type Accounts array with 0 to n Account */
    200: {
      body: Accounts;
    };
  }>
> =>
  openAPIFetch(
    config,
    {
      path: "/Accounts",
      method: "get",
      requestSchema: z.object({
        query: z.object({
          where: z.string().optional(),
          order: z.string().optional(),
        }).optional(),
        headers: z.object({
          "xero-tenant-id": z.string(),
          "If-Modified-Since": z.string().optional(),
        }),
      }),
      responseSchema: {
        200: z.object({ body: AccountsSchema }),
      },
    },
    request,
  ) as any;

/**
 * Creates a new chart of accounts
 */
export const createAccount = (config: OpenAPIClientConfig, request: {
  headers: {
    /** Xero identifier for Tenant */
    "xero-tenant-id": string;
    /** This allows you to safely retry requests without the risk of duplicate processing. 128 character max. */
    "Idempotency-Key"?: string;
  };
  body: Account;
}): Promise<
  OpenAPIResponses<{
    /** Success - created new Account and return response of type Accounts array with new Account */
    200: {
      body: Accounts;
    };
    /** Validation Error - some data was incorrect returns response of type Error */
    400: {
      body: Error;
    };
  }>
> =>
  openAPIFetch(
    config,
    {
      path: "/Accounts",
      method: "put",
      requestSchema: z.object({
        headers: z.object({
          "xero-tenant-id": z.string(),
          "Idempotency-Key": z.string().optional(),
        }),
        body: AccountSchema,
      }),
      responseSchema: {
        200: z.object({ body: AccountsSchema }),
        400: z.object({ body: ErrorSchema }),
      },
    },
    request,
  ) as any;

